@SpringBootTest(properties={"testhub.registration.enabled=true","testhub.bootstrap.demo-enabled=false"})
@AutoConfigureMockMvc @ActiveProfiles(resolver=FunctionalDatabaseProfile.class) @DirtiesContext
class QualityReportSyncFlowTests {
 @TempDir static Path directory;
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){if(FunctionalDatabaseProfile.mysql())FunctionalDatabaseProfile.configure(r,directory,"quality-sync-fixture");else{r.add("testhub.desktop.data-directory",directory::toString);r.add("spring.datasource.url",()->"jdbc:h2:file:"+directory.resolve("workspace")+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_ON_EXIT=FALSE");r.add("spring.datasource.username",()->"sa");r.add("spring.datasource.password",()->"quality-sync-fixture");}}
 @Autowired RegistrationService registration; @Autowired AccessService access; @Autowired QualityReportSyncService sync; @Autowired QualityReportScheduleService schedules; @Autowired QualityReportScheduleRepository repository; @Autowired Scheduler quartz; @Autowired JdbcClient jdbc; @Autowired ObjectMapper json; @Autowired MockMvc mvc; @Autowired PlatformTransactionManager transactions;
 record Fixture(PlatformUserPrincipal actor,String project,String org){}
 Fixture fixture(){String account="quality-sync-"+UUID.randomUUID();var actor=new PlatformUserPrincipal(registration.register(account,account+"@example.test","报告同步验收","Quality-fixture-2026!"));var c=access.context(actor);String org=c.organizations().getFirst().id();return new Fixture(actor,c.projects().get(org).getFirst().id(),org);}
 String extra(Fixture f,String code){return access.createProject(f.actor(),"隔离关联项目 "+code,code,"").id();}
 QualityReportScheduleService.ScheduleInput input(String name,List<String> projects,int days,boolean enabled){return new QualityReportScheduleService.ScheduleInput(name,projects,"0 0 0 1 1 ? 2099","Asia/Shanghai",days,enabled);}
 Snapshot snapshot(Fixture f){return sync.snapshot(f.actor(),f.project(),f.actor().userId());}
 Item item(String name,List<String> projects,int days){return new Item("SCHEDULE",name,new Definition(projects,"0 0 0 1 1 ? 2099","Asia/Shanghai",days));}
 Request request(Fixture f,Item... items){return new Request(UUID.randomUUID().toString(),f.actor().userId(),snapshot(f).revision(),Arrays.stream(items).map(i->new Operation(UUID.randomUUID().toString(),i)).toList());}
 Receipt apply(Fixture f,Request r){return sync.apply(f.actor(),f.project(),r);}
 JobKey job(String id){return new JobKey(id,"testhub-quality-report");}
 long receipts(Fixture f){return jdbc.sql("SELECT COUNT(*) FROM quality_report_sync_receipt WHERE project_id=:p").param("p",f.project()).query(Long.class).single();}
 @Test void copiesExplicitOrderedProjectsDisabledWithoutRunsNotificationsOrDuplicateReceipt()throws Exception{var f=fixture();String link=extra(f,"TARGET_DIFFERENT_CODE");var r=request(f,item("周报",List.of(link,f.project()),7));var receipt=apply(f,r);assertEquals(receipt,apply(f,r));var result=repository.findById(receipt.results().getFirst().id()).orElseThrow();assertEquals(List.of(link,f.project()),result.projectIds());assertFalse(result.enabled());assertFalse(quartz.checkExists(job(result.id())));assertTrue(schedules.runs(f.actor(),result.id()).isEmpty());assertEquals(0,jdbc.sql("SELECT COUNT(*) FROM notification_delivery WHERE organization_id=:o").param("o",f.org()).query(Long.class).single());assertEquals(1,receipts(f));assertEquals(1,schedules.list(f.actor()).size());assertThrows(ResponseStatusException.class,()->schedules.runNow(f.actor(),result.id()));}
 @Test void changedDestinationDisablesQuartzAndPreservesLocalRunsCreatorAndLastResult()throws Exception{var f=fixture();var row=schedules.create(f.actor(),input("周报",List.of(f.project()),7,true));var run=schedules.runNow(f.actor(),row.id());assertEquals("SUCCEEDED",run.status());assertTrue(quartz.checkExists(job(row.id())));apply(f,request(f,item("周报",List.of(f.project()),30)));var result=repository.findById(row.id()).orElseThrow();assertFalse(result.enabled());assertEquals(30,result.periodDays());assertEquals(row.createdBy(),result.createdBy());assertEquals(run.id(),result.lastRunId());assertEquals(run,schedules.runs(f.actor(),row.id()).getFirst());assertFalse(quartz.checkExists(job(row.id())));}
 @Test void unchangedConfigurationKeepsNativeActivationAndManualEnableStillRunsLocalReports()throws Exception{var f=fixture();var row=schedules.create(f.actor(),input("周报",List.of(f.project()),7,true));long version=snapshot(f).itemVersions().get("SCHEDULE\n周报");apply(f,request(f,item("周报",List.of(f.project()),7)));assertTrue(repository.findById(row.id()).orElseThrow().enabled());assertTrue(quartz.checkExists(job(row.id())));assertEquals(version,snapshot(f).itemVersions().get("SCHEDULE\n周报"));assertEquals("SUCCEEDED",schedules.runNow(f.actor(),row.id()).status());}
 @Test void receiptReplayNeverRedisablesManuallyEnabledOrRecreatedTarget()throws Exception{var f=fixture();var r=request(f,item("周报",List.of(f.project()),7));var receipt=apply(f,r);String id=receipt.results().getFirst().id();schedules.update(f.actor(),id,input("周报",List.of(f.project()),7,true));assertThrows(ResponseStatusException.class,()->apply(f,r));assertTrue(repository.findById(id).orElseThrow().enabled());schedules.delete(f.actor(),id);var replacement=schedules.create(f.actor(),input("周报",List.of(f.project()),7,true));assertNotEquals(id,replacement.id());assertThrows(ResponseStatusException.class,()->apply(f,r));assertTrue(repository.findById(replacement.id()).orElseThrow().enabled());assertEquals(1,schedules.list(f.actor()).size());}
 @Test void committedUuidCannotChangePayloadAndDeletedCopyCannotBeRebuilt(){var f=fixture();var r=request(f,item("周报",List.of(f.project()),7));var receipt=apply(f,r);var changed=new Request(r.requestKey(),r.expectedUserId(),"f".repeat(64),r.operations());assertThrows(ResponseStatusException.class,()->apply(f,changed));schedules.delete(f.actor(),receipt.results().getFirst().id());assertThrows(ResponseStatusException.class,()->apply(f,r));assertTrue(schedules.list(f.actor()).isEmpty());}
 @Test void nativeConfigurationVersionProtectsConcurrentActivationAndCrossAnchorEdits(){var f=fixture();String linked=extra(f,"LINKED");var row=schedules.create(f.actor(),input("周报",List.of(linked,f.project()),7,false));var stale=request(f,item("周报",List.of(f.project()),30));schedules.update(f.actor(),row.id(),input("周报",List.of(linked,f.project()),7,true));assertThrows(ResponseStatusException.class,()->apply(f,stale));var before=sync.snapshot(f.actor(),linked,f.actor().userId());apply(f,request(f,item("周报",List.of(linked,f.project()),14)));assertNotEquals(before.revision(),sync.snapshot(f.actor(),linked,f.actor().userId()).revision());assertFalse(repository.findById(row.id()).orElseThrow().enabled());}
 @Test void lateOccupiedNameRollsBackChangesReceiptVersionAndKeepsOldQuartzJob()throws Exception{var f=fixture();String other=extra(f,"OTHER");var row=schedules.create(f.actor(),input("原计划",List.of(f.project()),7,true));schedules.create(f.actor(),input("范围外同名",List.of(other),7,true));var before=snapshot(f);var r=request(f,item("原计划",List.of(f.project()),30),item("范围外同名",List.of(f.project()),14));assertThrows(ResponseStatusException.class,()->apply(f,r));assertEquals(before,snapshot(f));assertTrue(repository.findById(row.id()).orElseThrow().enabled());assertTrue(quartz.checkExists(job(row.id())));assertEquals(0,receipts(f));}
 @Test void explicitTransactionRollbackDoesNotRemoveQuartzJob()throws Exception{var f=fixture();var row=schedules.create(f.actor(),input("周报",List.of(f.project()),7,true));var r=request(f,item("周报",List.of(f.project()),30));new TransactionTemplate(transactions).executeWithoutResult(tx->{apply(f,r);assertTrue(quartzCheck(row.id()));tx.setRollbackOnly();});assertTrue(repository.findById(row.id()).orElseThrow().enabled());assertTrue(quartz.checkExists(job(row.id())));assertEquals(0,receipts(f));}
 boolean quartzCheck(String id){try{return quartz.checkExists(job(id));}catch(Exception e){throw new IllegalStateException(e);}}
 @Test void crossOrganizationMissingAnchorUnknownProjectsAndDuplicateScopesNeverWrite(){var f=fixture();var other=fixture();for(var projects:List.of(List.of(other.project(),f.project()),List.of(other.project()),List.of(f.project(),f.project()),List.of("0".repeat(26),f.project())))assertThrows(RuntimeException.class,()->apply(f,request(f,item("周报",projects,7))));assertTrue(schedules.list(f.actor()).isEmpty());assertEquals(0,receipts(f));}
 @Test void validationCsrfActorProjectAndReadOnlyRolesAreEnforced()throws Exception{var f=fixture();var other=fixture();String route="/api/v1/projects/"+f.project()+"/quality-report/sync";var r=request(f,item("周报",List.of(f.project()),7));mvc.perform(post(route).with(user(f.actor())).contentType("application/json").content(json.writeValueAsBytes(r))).andExpect(status().isForbidden());mvc.perform(get(route).with(user(other.actor())).param("expectedUserId",other.actor().userId())).andExpect(status().isForbidden());assertThrows(ResponseStatusException.class,()->sync.snapshot(f.actor(),f.project(),other.actor().userId()));jdbc.sql("UPDATE membership SET role_code='VIEWER' WHERE user_id=:u").param("u",f.actor().userId()).update();mvc.perform(get(route).with(user(f.actor())).param("expectedUserId",f.actor().userId())).andExpect(status().isForbidden());mvc.perform(post(route).with(user(f.actor())).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(r))).andExpect(status().isForbidden());}
 @Test void strictProtocolRejectsUnknownActivationHistoryAndInvalidRules()throws Exception{var f=fixture();var r=request(f,item("周报",List.of(f.project()),7));for(String field:List.of("enabled","history","statistics")){var body=json.valueToTree(r);((com.fasterxml.jackson.databind.node.ObjectNode)body.path("operations").get(0).path("item").path("definition")).put(field,true);assertThrows(ResponseStatusException.class,()->sync.decode(json.writeValueAsBytes(body)));}assertThrows(ResponseStatusException.class,()->sync.decode("null".getBytes()));assertEquals(413,assertThrows(ResponseStatusException.class,()->sync.decode(new byte[QualityReportSyncService.MAX_BYTES+1])).getStatusCode().value());for(var i:List.of(new Item("SCHEDULE","周报",new Definition(List.of(f.project()),"invalid","UTC",7)),new Item("SCHEDULE","周报",new Definition(List.of(f.project()),"0 0 0 1 1 ? 2099","bad/zone",7)),item("周报",List.of(f.project()),91)))assertThrows(ResponseStatusException.class,()->apply(f,request(f,i)));assertTrue(schedules.list(f.actor()).isEmpty());}
 @Test void boundedBatchAndOrganizationCapacityRejectWithoutTruncation(){var f=fixture();var value=item("周报",List.of(f.project()),7);var r=new Request(UUID.randomUUID().toString(),f.actor().userId(),snapshot(f).revision(),java.util.stream.IntStream.range(0,21).mapToObj(n->new Operation(UUID.randomUUID().toString(),item("周报"+n,List.of(f.project()),7))).toList());assertThrows(ResponseStatusException.class,()->apply(f,r));for(int n=0;n<1001;n++)repository.insert(com.github.f4b6a3.ulid.UlidCreator.getUlid().toString(),f.org(),"容量 "+n,List.of(f.project()),value.definition().cronExpression(),"UTC",7,false,f.actor().userId());assertThrows(ResponseStatusException.class,()->snapshot(f));assertEquals(0,receipts(f));}
 @Test void scalarCoercionsNullFieldsAndDuplicateJsonKeysCannotChangePlan()throws Exception{var f=fixture();var r=request(f,item("周报",List.of(f.project()),7));for(String field:List.of("periodDays","projectIds","cronExpression")){var root=json.valueToTree(r);var d=(com.fasterxml.jackson.databind.node.ObjectNode)root.path("operations").get(0).path("item").path("definition");if(field.equals("periodDays"))d.put(field,"7");else if(field.equals("projectIds"))d.putArray(field).add(123);else d.putNull(field);assertThrows(ResponseStatusException.class,()->sync.decode(json.writeValueAsBytes(root)));}String raw=json.writeValueAsString(r).replace("\"periodDays\":7","\"periodDays\":7,\"periodDays\":30");assertThrows(ResponseStatusException.class,()->sync.decode(raw.getBytes()));assertTrue(schedules.list(f.actor()).isEmpty());}

 @Test void concurrentRequestsSerializeCasAndExactUuidReplay()throws Exception{for(boolean sameUuid:List.of(false,true)){var f=fixture();var first=request(f,item("并发计划",List.of(f.project()),7));var second=sameUuid?first:new Request(UUID.randomUUID().toString(),first.expectedUserId(),first.expectedRevision(),List.of(new Operation(UUID.randomUUID().toString(),item("并发计划",List.of(f.project()),14))));var start=new java.util.concurrent.CountDownLatch(1);try(var executor=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=executor.submit(()->{start.await();try{return (Object)apply(f,first);}catch(ResponseStatusException e){return e.getStatusCode().value();}});var b=executor.submit(()->{start.await();try{return (Object)apply(f,second);}catch(ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var outcomes=List.of(a.get(20,java.util.concurrent.TimeUnit.SECONDS),b.get(20,java.util.concurrent.TimeUnit.SECONDS));assertEquals(sameUuid?2:1,outcomes.stream().filter(Receipt.class::isInstance).count());if(!sameUuid)assertTrue(outcomes.contains(409));else assertEquals(outcomes.getFirst(),outcomes.getLast());assertEquals(1,receipts(f));assertEquals(1,schedules.list(f.actor()).size());assertFalse(schedules.list(f.actor()).getFirst().enabled());}}}

}
